def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def isSymmetric(tree):
    vals, left, right = _links(tree)
    if not vals:
        return True
    stack = [(left[0], right[0])]
    while stack:
        a, b = stack.pop()
        if a == -1 and b == -1:
            continue
        if a == -1 or b == -1 or vals[a] != vals[b]:
            return False
        stack.append((left[a], right[b]))
        stack.append((right[a], left[b]))
    return True
